use std::fs

fn main() {
    let limit = 200000
    let mut is_p: Vec<bool> = [true; 200001]
    let mut count: Vec<int> = [0; 200001]
    let mut last: Vec<int> = [0; 200001]
    is_p[0] = false
    is_p[1] = false
    let mut i = 2
    while i * i <= limit {
        if is_p[i] {
            let mut j = i * i
            while j <= limit {
                is_p[j] = false
                j += i
            }
        }
        i += 1
    }
    let mut c = 0
    let mut l = 0
    let mut k = 0
    while k <= limit {
        if is_p[k] {
            c += 1
            l = k
        }
        count[k] = c
        last[k] = l
        k += 1
    }
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut first = true
    let mut out: Vec<string> = []
    for line in text.lines() {
        let t = line.trim()
        if t.len() == 0 { continue }
        if first {
            first = false
            continue
        }
        let n = t.parse::<int>().unwrap_or(0)
        if last[n] == 0 {
            out.push("0 none")
        } else {
            out.push("${count[n]} ${last[n]}")
        }
    }
    println(out.join("\n"))
}

